const repository = 'god-friend-leibniz/AI-Techonology';

const weekEnd = $now.startOf('week');
const weekStart = weekEnd.minus({ weeks: 1 });
const start = weekStart.toISO({ suppressMilliseconds: true });
const lastSecond = weekEnd.minus({ seconds: 1 })
  .toISO({ suppressMilliseconds: true });

const filters = {
  bug: 'label:bug',
  task: 'label:task',
  feature: 'label:feature',
  unclassified: '-label:bug -label:task -label:feature',
};

const scope = `repo:${repository} is:issue created:${start}..${lastSecond}`;

return Object.entries(filters).map(([category, filter]) => ({
  json: {
    category,
    repository,
    weekStart: weekStart.toISODate(),
    weekEnd: weekEnd.toISODate(),
    q: `${scope} ${filter}`,
  },
}));

const { repository, weekStart, weekEnd } = $('Prepare Weekly Issues').first().json;
const types = ['bug', 'task', 'feature'];
const byType = { bug: 0, task: 0, feature: 0, unclassified: 0 };
const authorCounts = new Map();
const seen = new Set();

for (const { json: page } of $input.all()) {
  if (!Array.isArray(page.items)) {
    throw new Error('В ответе GitHub отсутствует массив items.');
  }

  if (page.incomplete_results || page.total_count > 1000) {
    throw new Error('GitHub вернул неполные результаты поиска.');
  }

  for (const issue of page.items) {
    if (seen.has(issue.id)) continue;
    seen.add(issue.id);

    const labels = issue.labels.map(label => label.name.toLowerCase());
    const type = types.find(name => labels.includes(name)) ?? 'unclassified';
    const login = issue.user?.login ?? '(неизвестен)';

    byType[type]++;
    authorCounts.set(login, (authorCounts.get(login) ?? 0) + 1);
  }
}

const byAuthor = Array.from(authorCounts, ([login, count]) => ({ login, count }));
byAuthor.sort((a, b) => b.count - a.count || a.login.localeCompare(b.login));

return [{
  json: { repository, weekStart, weekEnd, total: seen.size, byType, byAuthor },
}];

const stats = $('Group Weekly Issues').first().json;
const { weekStart, weekEnd, total, byType, byAuthor } = stats;

const lastDay = new Date(`${weekEnd}T00:00:00Z`);
lastDay.setUTCDate(lastDay.getUTCDate() - 1);
const period = `${weekStart} — ${lastDay.toISOString().slice(0, 10)}`;

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function table(headers, rows) {
  const cellStyle = 'border:1px solid #ddd;padding:6px 10px;text-align:left';
  const head = headers.map(header =>
    `<th scope="col" style="${cellStyle}">${escapeHtml(header)}</th>`
  ).join('');
  const body = rows.map(row =>
    `<tr>${row.map(value =>
      `<td style="${cellStyle}">${escapeHtml(value)}</td>`
    ).join('')}</tr>`
  ).join('');

  return `<table style="border-collapse:collapse">
    <thead><tr>${head}</tr></thead>
    <tbody>${body}</tbody>
  </table>`;
}

const previous = $json.stats_json ? JSON.parse($json.stats_json) : null;

const delta = previous ? {
  total: total - previous.total,
  byType: Object.fromEntries(Object.keys(byType).map(type => [
    type,
    byType[type] - (previous.byType[type] ?? 0),
  ])),
} : null;

const formatDelta = value => value > 0 ? `+${value}` : String(value);

const typeRows = [
  ['Баги', 'bug'],
  ['Задачи', 'task'],
  ['Запросы на новые функции', 'feature'],
  ['Без категории', 'unclassified'],
].map(([label, type]) => [
  label,
  byType[type],
  delta ? formatDelta(delta.byType[type]) : '—',
]);

const comparison = delta
  ? `<p>Изменение к прошлой неделе <strong>${formatDelta(delta.total)}</strong></p>`
  : '<p>Нет данных за предыдущую неделю.</p>';
const authorRows = byAuthor.map(({ login, count }) => [login, count]);
const authorSection = authorRows.length
  ? table(['Автор', 'Issues'], authorRows)
  : '<p>За неделю новых Issues не было.</p>';

const subject = `Еженедельный отчёт по GitHub Issues — ${period}`;
const html = `
  <h1>GitHub Issues за неделю</h1>
  <p>Период <strong>${period}</strong></p>
  <p>Всего новых Issues <strong>${total}</strong></p>
  ${comparison}
  <h2>По типам</h2>
  ${table(['Тип', 'Issues', 'Δ'], typeRows)}
  <h2>По авторам</h2>
  ${authorSection}
`;

return { json: { ...stats, delta, subject, html } };

const report = $('Build Weekly Email').first().json;
const annotation = typeof $json.text === 'string' ? $json.text.trim() : '';

const message = annotation || 'AI-комментарий временно недоступен.';
const safeMessage = message
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replace(/\r?\n/g, '<br>');

const html = report.html + `
  <h2>AI-комментарий недели</h2>
  <p>${safeMessage}</p>
`;

return { json: { ...report, html } };
